import 'package:firebase_core/firebase_core.dart';
import 'package:firebase_messaging/firebase_messaging.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:sentry_flutter/sentry_flutter.dart';
import 'package:dealsouk/app/app.dart';
import 'package:dealsouk/features/admin/presentation/admin_app.dart';
import 'package:dealsouk/firebase_options.dart';

// Generated by `flutterfire configure` — run setup.sh if this import fails

const bool _adminMode = bool.fromEnvironment('ADMIN_MODE', defaultValue: false);

// G1: crash/error monitoring (PRD §12). Pass --dart-define=SENTRY_DSN=... to
// enable; with no DSN the app runs exactly as before (no Sentry init).
const String _sentryDsn = String.fromEnvironment('SENTRY_DSN');

/// Background FCM handler — must be top-level function
@pragma('vm:entry-point')
Future<void> _firebaseMessagingBackgroundHandler(RemoteMessage message) async {
  try {
    await Firebase.initializeApp(
      options: DefaultFirebaseOptions.currentPlatform,
    );
  } catch (e) {
    debugPrint('Firebase background initialization failed: $e');
  }
}

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  try {
    await Firebase.initializeApp(
      options: DefaultFirebaseOptions.currentPlatform,
    );
  } catch (e) {
    debugPrint(
      'Firebase initialization failed: $e. Running in mock/offline mode.',
    );
  }

  // FCM background handler (mobile only — web doesn't support this)
  if (!kIsWeb) {
    try {
      FirebaseMessaging.onBackgroundMessage(
        _firebaseMessagingBackgroundHandler,
      );
    } catch (e) {
      debugPrint('FCM configuration failed: $e');
    }
  }

  final app = ProviderScope(
    child: _adminMode ? const AdminApp() : const DealSoukApp(),
  );

  if (_sentryDsn.isEmpty) {
    runApp(app);
  } else {
    await SentryFlutter.init(
      (options) {
        options.dsn = _sentryDsn;
        options.tracesSampleRate = 0.1;
      },
      appRunner: () => runApp(app),
    );
  }
}
